s('219.6s', 'ismael-wind', 'Close on the indigo streaming against the sun, the young staff bending and springing back.')
s(56, 'yes', 'On "Yes" the light opens over the red cloth and the staff together; every leaf answers.')
s(57, 'isaac', 'The cradle, three gold bells on its hoop; on "Isaac" the bells laugh and the cradle begins to rock.')
s(58, 'with-him', 'The cord runs out from the staff across the rug to the cradle, winds on its rim and draws tight; light goes along it.')
s(60, 'seed-after-him', 'A field of wheat, green to gold in one wave of wind and light, ears filling and bowing.')
s(61, 'i-have-heard', 'The light turns and comes to the indigo cloth, hanging low; on "heard" it lifts its head.')
